    "solution": "**1. Центр, сокращения и настоящие полюса.** Положим \\(u=z-(2 + 2 i)\\). После объединения дробей и сокращения общих множителей получаем $$f{\\left(z \\right)} = \\frac{u \\left(2 + i\\right) + 2 + 6 i}{u^{2} + u \\left(6 + 3 i\\right) + 6 + 8 i}$$ Сокращённый знаменатель факторизуется как $$\\left(u + 2 + i\\right) \\left(u + 4 + 2 i\\right)$$ Его нули (координаты относительно центра) и порядки: \\(-2 - i\\), порядок 1, расстояние \\(\\sqrt{5}\\), \\(-4 - 2 i\\), порядок 1, расстояние \\(2 \\sqrt{5}\\).\n\n**2. Выбор кольца.** У заданной точки \\(z_0=-1\\) расстояние до центра равно \\(|z_0-c|=\\sqrt{13}\\). Из всех радиусов выбираем ближайший меньший \\(\\sqrt{5}\\) и ближайший больший \\(2 \\sqrt{5}\\): $$\\sqrt{5}<|u|<2 \\sqrt{5}.$$ Каждый конечный ненулевой край проходит через полюс; поэтому расширить это кольцо, сохранив тот же центр и одну сумму ряда, нельзя.\n\n**3. Простые дроби и их коэффициенты.** Для полюса \\(a\\) порядка \\(m\\) коэффициент при \\((u-a)^{-k}\\) равен $$A_k=\\frac{1}{(m-k)!}\\left[\\frac{d^{m-k}}{du^{m-k}}\\bigl((u-a)^m f(u+c)\\bigr)\\right]_{u=a}.$$ В этой задаче это даёт:$$f(z)=\\frac{i}{u + 2 + i}+\\frac{2}{u + 4 + 2 i}.$$\n\nДля дроби \\(\\frac{i}{u + 2 + i}\\) берём \\(q=a/u=-2 - i/u\\). Во всём выбранном кольце \\(|q|<1\\), так как \\(|u|>\\sqrt{5}\\). Поэтому $$\\frac{i}{u + 2 + i}=i\\,u^{-1}\\left(1-\\frac{-2 - i}u\\right)^{-1}=\\sum_{n=0}^{\\infty}\\left(i\\right)\\binom{n+0}{0}\\frac{(-2 - i)^n}{u^{n+1}}.$$\n\nДля дроби \\(\\frac{2}{u + 4 + 2 i}\\) берём \\(q=u/a=u/(-4 - 2 i)\\). Теперь \\(|q|<1\\), потому что \\(|u|<2 \\sqrt{5}\\). Поэтому $$\\frac{2}{u + 4 + 2 i}=\\frac{2}{5} - \\frac{i}{5}\\left(1-\\frac{u}{-4 - 2 i}\\right)^{-1}=\\sum_{n=0}^{\\infty}\\left(\\frac{2}{5} - \\frac{i}{5}\\right)\\binom{n+0}{0}\\left(\\frac{u}{-4 - 2 i}\\right)^n.$$\n\n**4. Итог.** Складываем все полученные ряды; их общая область сходимости — пересечение использованных неравенств:$$f(z)=\\sum_{n=0}^{\\infty}\\left(i\\right)\\binom{n+0}{0}\\frac{(-2 - i)^n}{u^{n+1}}+\\sum_{n=0}^{\\infty}\\left(\\frac{2}{5} - \\frac{i}{5}\\right)\\binom{n+0}{0}\\left(\\frac{u}{-4 - 2 i}\\right)^n,\\qquad \\sqrt{5}<|u|<2 \\sqrt{5}.$$ Обобщённый геометрический ряд выведен в блоке «Метод». Члены вида \\(u^{-j}\\) образуют главную часть, а неотрицательные степени — регулярную часть.",
    "answer": "$$f(z)=\\sum_{n=0}^{\\infty}\\left(i\\right)\\binom{n+0}{0}\\frac{(-2 - i)^n}{u^{n+1}}+\\sum_{n=0}^{\\infty}\\left(\\frac{2}{5} - \\frac{i}{5}\\right)\\binom{n+0}{0}\\left(\\frac{u}{-4 - 2 i}\\right)^n,\\qquad \\sqrt{5}<|u|<2 \\sqrt{5}.$$",
