    "solution": "**1. Центр, сокращения и настоящие полюса.** Положим \\(u=z-(-2)\\). После объединения дробей и сокращения общих множителей получаем $$f{\\left(z \\right)} = \\frac{5 u - 10 + 2 i}{u^{2} + u \\left(-3 + i\\right) - 4 - 4 i}$$ Сокращённый знаменатель факторизуется как $$\\left(u - 4\\right) \\left(u + 1 + i\\right)$$ Его нули (координаты относительно центра) и порядки: \\(4\\), порядок 1, расстояние \\(4\\), \\(-1 - i\\), порядок 1, расстояние \\(\\sqrt{2}\\).\n\n**2. Выбор кольца.** У заданной точки \\(z_0=-2 + 2 i\\) расстояние до центра равно \\(|z_0-c|=2\\). Из всех радиусов выбираем ближайший меньший \\(\\sqrt{2}\\) и ближайший больший \\(4\\): $$\\sqrt{2}<|u|<4.$$ Каждый конечный ненулевой край проходит через полюс; поэтому расширить это кольцо, сохранив тот же центр и одну сумму ряда, нельзя.\n\n**3. Простые дроби и их коэффициенты.** Для полюса \\(a\\) порядка \\(m\\) коэффициент при \\((u-a)^{-k}\\) равен $$A_k=\\frac{1}{(m-k)!}\\left[\\frac{d^{m-k}}{du^{m-k}}\\bigl((u-a)^m f(u+c)\\bigr)\\right]_{u=a}.$$ В этой задаче это даёт:$$f(z)=\\frac{2}{u - 4}+\\frac{3}{u + 1 + i}.$$\n\nДля дроби \\(\\frac{2}{u - 4}\\) берём \\(q=u/a=u/(4)\\). Теперь \\(|q|<1\\), потому что \\(|u|<4\\). Поэтому $$\\frac{2}{u - 4}=- \\frac{1}{2}\\left(1-\\frac{u}{4}\\right)^{-1}=\\sum_{n=0}^{\\infty}\\left(- \\frac{1}{2}\\right)\\binom{n+0}{0}\\left(\\frac{u}{4}\\right)^n.$$\n\nДля дроби \\(\\frac{3}{u + 1 + i}\\) берём \\(q=a/u=-1 - i/u\\). Во всём выбранном кольце \\(|q|<1\\), так как \\(|u|>\\sqrt{2}\\). Поэтому $$\\frac{3}{u + 1 + i}=3\\,u^{-1}\\left(1-\\frac{-1 - i}u\\right)^{-1}=\\sum_{n=0}^{\\infty}\\left(3\\right)\\binom{n+0}{0}\\frac{(-1 - i)^n}{u^{n+1}}.$$\n\n**4. Итог.** Складываем все полученные ряды; их общая область сходимости — пересечение использованных неравенств:$$f(z)=\\sum_{n=0}^{\\infty}\\left(- \\frac{1}{2}\\right)\\binom{n+0}{0}\\left(\\frac{u}{4}\\right)^n+\\sum_{n=0}^{\\infty}\\left(3\\right)\\binom{n+0}{0}\\frac{(-1 - i)^n}{u^{n+1}},\\qquad \\sqrt{2}<|u|<4.$$ Обобщённый геометрический ряд выведен в блоке «Метод». Члены вида \\(u^{-j}\\) образуют главную часть, а неотрицательные степени — регулярную часть.",
