    "statementPretty": "Разложить в ряд Лорана по степеням z в кольце, содержащем \\(z_0=1+2i\\), исходную функцию\n$$f(z)=\\frac{z(4+i)+12i+3}{z^2+2iz+15}+\\frac{3z(i-1)+6}{z^2+z(1-3i)-3i}.$$\nУказать границы сходимости и объяснить роль точки z=3i."
