    "solution": "**1. Сходимость и переход к экспонентам.** Используем \\(\\cos v=(e^{iv}+e^{-iv})/2\\), \\(\\sin v=(e^{iv}-e^{-iv})/(2i)\\). После раскрытия именно данного подынтегрального выражения получаем:$$\\frac{x^{2}}{\\left(x^{4} + 24 x^{2}\\right) + 400}=\\frac{x^{2}}{x^{4} + 24 x^{2} + 400}.$$ Если рациональная часть убывает лишь как \\(1/x\\), каждый осциллирующий несобственный интеграл существует на обоих концах по признаку Дирихле. При более быстром убывании он сходится абсолютно. Частоты, знак фазы и комплексные коэффициенты сохраняем в раскрытии.\n\n**2. Контур и конкретные вычеты.**\n\nДля частоты \\(k=0\\) рассматриваем $$F_k(z)=\\frac{z^{2}}{z^{4} + 24 z^{2} + 400}.$$ Замыкаем вверх (положительная ориентация). Полюса сокращённой рациональной части: \\(2 - 4 i\\) (порядок 1), \\(2 + 4 i\\) (порядок 1), \\(-2 - 4 i\\) (порядок 1), \\(-2 + 4 i\\) (порядок 1). Интеграл по дуге оценивается как \\(\\pi R\\cdot O(R^{-2})\\to0\\).\n\nВнутри находится \\(2 + 4 i\\). Убираем его полюс: $$H(z)=(z-(2 + 4 i))^{1}F_k(z)=\\frac{z^{2}}{\\left(z - 2 + 4 i\\right) \\left(z + 2 - 4 i\\right) \\left(z + 2 + 4 i\\right)}.$$Вычет равен значению голоморфной части: $$\\operatorname{Res}_{z=2 + 4 i}F_k=H(2 + 4 i)=\\frac{1}{16} - \\frac{i}{32}.$$\n\nВнутри находится \\(-2 + 4 i\\). Убираем его полюс: $$H(z)=(z-(-2 + 4 i))^{1}F_k(z)=\\frac{z^{2}}{\\left(z - 2 - 4 i\\right) \\left(z - 2 + 4 i\\right) \\left(z + 2 + 4 i\\right)}.$$Вычет равен значению голоморфной части: $$\\operatorname{Res}_{z=-2 + 4 i}F_k=H(-2 + 4 i)=- \\frac{1}{16} - \\frac{i}{32}.$$ Итак, $$J_{0}=2\\pi i\\sum\\operatorname{Res}F_k=\\frac{\\pi}{8}.$$\n\n**3. Сумма компонент.** Складываем вычисленные комплексные интегралы с коэффициентами, уже включёнными в \\(F_k\\). Не нужно дополнительно брать действительную часть, если исходная рациональная функция имеет комплексные коэффициенты. Получаем $$\\frac{\\pi}{8}$$. Обоснование оценки дуги приведено в блоке «Метод».",
