  "2021-осень-v1-n6": {
    "answer": "$$I=\\frac{\\ln15-1}{18}.$$",
    "solution": "Положим \\(x=3t\\). Тогда \\(dx=3dt\\), и\n$$I=\\frac19\\left(\\ln15\\int_0^\\infty\\frac{dt}{(1+t)^3}+\\int_0^\\infty\\frac{\\ln t}{(1+t)^3}\\,dt\\right).$$\nПервый интеграл равен 1/2 по первообразной \\(-1/[2(1+t)^2]\\). Для второго найдём параметрический интеграл вычетами:\n$$M(s)=\\int_0^\\infty\\frac{t^{s-1}}{(1+t)^3}\\,dt,\\qquad 0<\\operatorname{Re}s<3.$$\nБерём \\(z^{s-1}=e^{(s-1)\\operatorname{Log}z}\\), \\(0<\\arg z<2\\pi\\), и контур вокруг положительной полуоси. Верхний берег направлен от 0 к ∞, нижний от ∞ к 0, поэтому их сумма равна \\((1-e^{2\\pi is})M(s)\\). Малый круг убывает как \\(\\varepsilon^{\\operatorname{Re}s}\\), большой как \\(R^{\\operatorname{Re}s-3}\\). Внутри только тройной полюс −1:\n$$\\operatorname{Res}_{-1}\\frac{z^{s-1}}{(1+z)^3}=\\frac{(s-1)(s-2)}2(-1)^{s-3}=-\\frac{(s-1)(s-2)}2e^{\\pi is}.$$\nДелим на \\(1-e^{2\\pi is}=-2ie^{\\pi is}\\sin\\pi s\\):\n$$M(s)=\\frac{\\pi(s-1)(s-2)}{2\\sin\\pi s}.$$\nПри \\(s=1+h\\) синус равен \\(-\\pi h+O(h^3)\\), числитель — \\(\\pi h(h-1)\\). Поэтому\n$$M(1+h)=\\frac12-\\frac h2+O(h^2),\\quad M(1)=\\frac12,\\quad M'(1)=-\\frac12.$$\nДифференцирование под интегралом допустимо в любой замкнутой внутренней полосе сходимости: дополнительный логарифм интегрируем на обоих концах. Значит\n$$\\int_0^\\infty\\frac{\\ln t}{(1+t)^3}\\,dt=-\\frac12,\\qquad I=\\frac19\\left(\\frac{\\ln15}2-\\frac12\\right)=\\frac{\\ln15-1}{18}.$$\nЭто исправляет прежнее значение −3/4 для логарифмического интеграла: правильное значение −1/2.",
    "methodRefs": [
      "mellin"
    ]
  },
  "2008-2009-осень-v84-n5": {
    "answer": "Положим \\(b=2^{-1/3}\\), \\(r_k=e^{2\\pi ik/3}\\),\n$$s_{\\sigma,k}=2^{-1/6}e^{i(\\sigma\\pi/12+2\\pi k/3)}.$$\nПри \\(L(p)=\\operatorname{Log}(1-b/p)\\), \\(Q(p)=1/(p-b)-1/p\\):\n$$I=\\operatorname{Re}(I_1+I_2),$$\n$$I_1=\\sum_{k=0}^2\\left[-\\frac{2r_k}3L(r_k)+\\frac{r_k^2}3Q(r_k)\\right],$$\n$$I_2=\\sum_{\\sigma=\\pm1}\\sum_{k=0}^2\\frac{\\sigma i}{2s_{\\sigma,k}^2}L(s_{\\sigma,k}).$$\nВсе логарифмы главные. Численно \\(I\\approx0.403342572956\\).",
    "solution": "Верхний предел в оригинале равен \\(1\\), поэтому сохраняем конечный интервал. Рационализируем кубический корень:\n$$t=\\sqrt[3]{\\frac{x}{x+1}},\\quad x=\\frac{t^3}{1-t^3},\\quad\n\\sqrt[3]{x(x+1)^2}=\\frac t{1-t^3},\\quad dx=\\frac{3t^2}{(1-t^3)^2}\\,dt.$$\nПри \\(x:0\\to1\\) получаем \\(t:0\\to b\\), \\(b=2^{-1/3}\\), и\n$$I=\\int_0^b R(t)\\,dt,\\qquad\nR(t)=\\frac{3t^6}{(1-t^3)^2(2t^6-2t^3+1)}.$$\nЭта рациональная функция имеет три двойных полюса \\(r_k=e^{2\\pi ik/3}\\), \\(k=0,1,2\\), и шесть простых полюсов\n$$s_{\\sigma,k}=2^{-1/6}e^{i(\\sigma\\pi/12+2\\pi k/3)},\\quad \\sigma=\\pm1,\\quad k=0,1,2.$$\nДействительно, \\(s_{\\sigma,k}^3=(1+\\sigma i)/2\\). Все полюса вне отрезка интегрирования.\n\nНайдём коэффициенты простых дробей через главные части. Для двойного полюса \\(r^3=1\\) положим \\(H(t)=(t-r)^2R(t)\\). Подстановка и дифференцирование дают\n$$H(r)=\\frac{r^2}3,\\qquad H'(r)=-\\frac{2r}3.$$\nПервый коэффициент стоит при \\((t-r)^{-2}\\), второй — при \\((t-r)^{-1}\\). Для простого полюса \\(s=s_{\\sigma,k}\\), \\(q=s^3\\), имеем\n$$\\operatorname{Res}_{s}R=\\frac{q^2}{2s^2(1-q)^2(2q-1)}=\\frac{\\sigma i}{2s^2}.$$\nПоэтому точное разложение:\n$$R(t)=\\sum_{k=0}^2\\left[-\\frac{2r_k}{3(t-r_k)}+\\frac{r_k^2}{3(t-r_k)^2}\\right]\n+\\sum_{\\sigma=\\pm1}\\sum_{k=0}^2\\frac{\\sigma i}{2s_{\\sigma,k}^2(t-s_{\\sigma,k})}.$$\nРазность правой и левой частей не имеет полюсов и стремится к нулю на бесконечности, а значит тождественно равна нулю.\n\nОстаётся интегрировать каждую простую дробь. Обозначим\n$$L(p)=\\operatorname{Log}(1-b/p),\\qquad Q(p)=\\frac1{p-b}-\\frac1p.$$\nТогда \\(\\int_0^b dt/(t-p)=L(p)\\), \\(\\int_0^b dt/(t-p)^2=Q(p)\\). Главный логарифм корректен: \\(b<|r_k|,|s_{\\sigma,k}|\\), поэтому \\(1-t/p\\) всё время имеет положительную вещественную часть и не пересекает разрез логарифма. Подставляя коэффициенты, получаем конечную сумму в ответе. Комплексно-сопряжённые слагаемые складываются в вещественное число; независимая численная квадратура исходного интеграла даёт \\(0.403342572956\\)."
  },
