    "solution": "Уравнение знаменателя \\(e^z=-e\\) даёт \\(z=1+(2k+1)\\pi i\\). В круге \\(|z-1|<4\\) находятся только \\(1\\pm\\pi i\\), поскольку \\(\\pi<4<3\\pi\\). Каждый полюс простой. В обеих точках \\(\\sinh z=-\\sinh1\\), а производная знаменателя равна \\(e^2\\). Поэтому каждый вычет равен \\(-e^{-2}\\sinh1\\); сумма \\(-2e^{-2}\\sinh1\\). Обычная теорема вычетов даёт \\(2\\pi i\\) этой суммы.\n\nОтвет:$$- \\frac{4 i \\pi \\sinh{\\left(1 \\right)}}{e^{2}}$$"
