    "solution": "Знаменатель равен \\((z^2+1)(z^2+9)\\). В -3i полюс сокращается множителем \\(z+3i\\). Существенная точка 0 и полюс -i находятся внутри; внешние полюса только i и 3i. Так удобнее избежать вычисления вычета существенной точки.\n\nВнешнее разложение в бесконечности:$$F(z)=0+O(z^{-2}),\\qquad\\operatorname{Res}_{\\infty}F=0.$$\n\nВнешний полюс \\(i\\), порядок 1: $$\\operatorname{Res}F=\\frac{\\cos{\\left(\\frac{1}{2} \\right)}}{2}.$$ Для простого полюса используем \\(N(a)/D^{\\prime}(a)\\), для повторного — соответствующую производную после удаления полюса.\n\nВнешний полюс \\(3 i\\), порядок 1: $$\\operatorname{Res}F=- \\frac{\\cos{\\left(\\frac{1}{6} \\right)}}{4}.$$ Для простого полюса используем \\(N(a)/D^{\\prime}(a)\\), для повторного — соответствующую производную после удаления полюса.\n\nОтвет:$$\\frac{i \\pi \\left(- 2 \\cos{\\left(\\frac{1}{2} \\right)} + \\cos{\\left(\\frac{1}{6} \\right)}\\right)}{2}$$"
