    "solution": "Нули знаменателя удовлетворяют \\(1/z^2=\\pm\\pi/3+2\\pi k\\). Максимальный модуль корня \\(\\sqrt{3/\\pi}<1\\), поэтому все корни лежат внутри окружности с центром i и радиусом 2. Снаружи конечных полюсов нет. Чтобы получить \\(1/z\\) после умножения на \\(z^7-2z^3\\), разлагаем знаменатель по \\(w=1/z\\) до \\(w^8\\).\n\nВнешнее разложение в бесконечности:$$F(z)=\\frac{12 z^{4} \\left(1 - z^{4}\\right) + 13}{6 z}+O(z^{-2}),\\qquad\\operatorname{Res}_{\\infty}F=- \\frac{13}{6}.$$\n\nОтвет:$$\\frac{13 i \\pi}{3}$$"
