    "solution": "Внутри находится существенная точка 0 и один ненулевой полюс \\(2 \\pi\\). Другие нули знаменателя вне контура: это проверяется расстоянием до его центра. Функция F чётная в окрестности нуля. Единственность ряда Лорана означает, что все нечётные степени отсутствуют; поэтому \\(\\operatorname{Res}_0F=0\\), несмотря на существенную особенность. В \\(a=2\\pi\\): знаменатель \\(h^2/2+O(h^4)\\), поэтому вычет \\(2[\\cos(1/z)]^{\\prime}_{z=a}=2\\sin(1/a)/a^2\\). В ряде знаменателя нет кубического члена, поэтому дополнительного вклада от него в вычет нет. Умножаем оставшийся вычет на \\(2\\pi i\\).\n\nОтвет:$$\\frac{i \\sin{\\left(\\frac{1}{2 \\pi} \\right)}}{\\pi}$$"
