    "solution": "Нули тригонометрического или гиперболического знаменателя образуют арифметическое семейство. Сравнение расстояний с радиусом показывает: внутри только \\(\\frac{\\pi}{2}\\). Полюс имеет порядок 2. При a=π/2 имеем \\(\\cos^2(a+h)=h^2+O(h^4)\\). Вычет равен \\(-ie^{-ia}=-1\\). Поскольку следующий член знаменателя имеет порядок h⁴, линейной поправки в удалённом полюсе нет. Поэтому достаточно первой производной числителя и множителя при h². Применяем обычную теорему вычетов.\n\nОтвет:$$- 2 i \\pi$$"
