    "solution": "Нули тригонометрического или гиперболического знаменателя образуют арифметическое семейство. Сравнение расстояний с радиусом показывает: внутри только \\(i \\pi\\). Полюс имеет порядок 2. При a=πi имеем \\(\\sinh^2(a+h)=h^2+O(h^4)\\). Вычет равен производной числителя \\(2(a+i)=2i(\\pi+1)\\). Поскольку следующий член знаменателя имеет порядок h⁴, линейной поправки в удалённом полюсе нет. Поэтому достаточно первой производной числителя и множителя при h². Применяем обычную теорему вычетов.\n\nОтвет:$$- 4 \\pi \\left(1 + \\pi\\right)$$"
