    "solution": "Уравнение \\(\\cot z=-i/2\\) эквивалентно \\(e^{2iz}=-1/3\\). Корни: \\((2k+1)\\pi/2+i\\ln3/2\\); внутри только \\(\\pm\\pi/2+i\\ln3/2\\). В положительном корне числитель нулевой, полюс устраним. В отрицательном числитель -2π. Производная знаменателя \\(-1-\\cot^2z=-3/4\\). Вычет равен \\(8\\pi/3\\). Полюса самого котангенса дают нули продолженной дроби и не являются полюсами F.\n\nОтвет:$$\\frac{16 i \\pi^{2}}{3}$$"
